package com.apple.spark.operator;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonInclude;
import io.fabric8.kubernetes.client.CustomResource;
import io.fabric8.kubernetes.model.annotation.Group;
import io.fabric8.kubernetes.model.annotation.Version;

@Version("v1beta2")
@Group("sparkoperator.k8s.io")
@JsonInclude(JsonInclude.Include.NON_NULL)
@JsonIgnoreProperties(ignoreUnknown = true)
public class SparkApplication extends CustomResource {

    private SparkApplicationSpec spec;

    private SparkApplicationStatus status;

    public SparkApplicationSpec getSpec() {
        return spec;
    }

    public void setSpec(SparkApplicationSpec spec) {
        this.spec = spec;
    }

    public SparkApplicationStatus getStatus() {
        return status;
    }

    public void setStatus(SparkApplicationStatus status) {
        this.status = status;
    }
}

